import { createElement, useRef } from '@wordpress/element';
import { __, sprintf } from '@wordpress/i18n';
import { Button, CheckboxControl, TextControl } from '@wordpress/components';
import { parseInlineBlankPrompt } from './inlineBlanks.mjs';
import { NumericalEditor, StructuredEditor } from './MathEditors';
import { MediaUpload } from '@wordpress/block-editor';
import { moveOption } from './model.mjs';

/** Private answer controls used by the question block; they save through the assessment writer. */
export function BankAnswerFields({ type, options = [], settings, onChange, prompt = '' }) {
  const dragged = useRef(null);
  const blanks = type === 'fill-in-the-blank' ? parseInlineBlankPrompt(prompt).answers : [];
  if (blanks.length)
    return (
      <div>
        <p>
          {__(
            'Write each correct answer inside curly brackets in the Question field. Preview shows draggable answers below the blanks.',
            'ohmylms',
          )}
        </p>
        <div className="ohmylms-blank-answer-bank">
          {blanks.map((answer) => (
            <span className="ohmylms-blank-answer-chip" key={answer.id}>
              {answer.text}
            </span>
          ))}
        </div>
        <CheckboxControl
          label={__('Case-sensitive answers', 'ohmylms')}
          checked={![false, 0, '0'].includes(settings.case_sensitive)}
          onChange={(case_sensitive) => onChange({ settings: { ...settings, case_sensitive } })}
        />
      </div>
    );
  if (type === 'numerical')
    return (
      <NumericalEditor
        value={settings}
        onChange={(patch) => onChange({ settings: { ...settings, ...patch } })}
      />
    );
  if (type === 'structured')
    return (
      <StructuredEditor
        value={settings}
        onChange={(patch) =>
          onChange({
            settings: {
              ...settings,
              ...patch,
              score: {
                enabled: true,
                value: (patch.parts || settings.parts || []).reduce(
                  (sum, part) => sum + Number(part.marks || 0),
                  0,
                ),
              },
            },
          })
        }
      />
    );
  if (['short-text', 'long-text'].includes(type))
    return <p>{__('Learners write their answer; a teacher marks it.', 'ohmylms')}</p>;
  if (type === 'statement')
    return <p>{__('The statement is the question content above.', 'ohmylms')}</p>;
  const choices = ['single-choice', 'multiple-choice', 'true-false'].includes(type);
  const patchOption = (index, patch) =>
    onChange({
      questions: options.map((option, position) =>
        position === index ? { ...option, ...patch } : option,
      ),
    });
  const reorder = (index, direction) => {
    const next = [...options];
    [next[index], next[index + direction]] = [next[index + direction], next[index]];
    onChange({
      questions: next.map((option, position) => ({ ...option, order_number: position + 1 })),
    });
  };
  return (
    <div className={`ohmylms-shared-answers ohmylms-bank-block-answers is-${type}`}>
      {type === 'fill-in-the-blank' && (
        <p>
          {__(
            'Use {answer} in the question for inline blanks, or enter accepted answers below.',
            'ohmylms',
          )}
        </p>
      )}
      {options.map((option, index) => (
        <fieldset
          key={option.id || index}
          className="ohmylms-shared-answer-row"
          onDragOver={(event) => event.preventDefault()}
          onDrop={(event) => {
            event.preventDefault();
            if (dragged.current !== null)
              onChange({ questions: moveOption(options, dragged.current, index) });
            dragged.current = null;
          }}
        >
          {choices && (
            <input
              className="ohmylms-shared-answer-correct"
              type={type === 'multiple-choice' ? 'checkbox' : 'radio'}
              aria-label={sprintf(__('Correct answer %d', 'ohmylms'), index + 1)}
              checked={option.is_correct === true || Number(option.is_correct) === 1}
              onChange={(event) =>
                onChange({
                  questions: options.map((item, position) => ({
                    ...item,
                    is_correct:
                      position === index
                        ? event.target.checked
                        : type === 'multiple-choice'
                          ? item.is_correct
                          : false,
                  })),
                })
              }
            />
          )}
          <TextControl
            label={sprintf(__('Answer %d', 'ohmylms'), index + 1)}
            hideLabelFromVision
            placeholder={sprintf(__('Option %d', 'ohmylms'), index + 1)}
            value={option.answer || ''}
            disabled={type === 'true-false'}
            onChange={(answer) => patchOption(index, { answer })}
          />
          {type !== 'true-false' && (
            <MediaUpload
              allowedTypes={['image']}
              value={option.thumbnail_id}
              onSelect={(image) =>
                patchOption(index, { thumbnail_id: image.id, image_url: image.url })
              }
              render={({ open }) => (
                <Button icon="format-image" label={__('Answer image', 'ohmylms')} onClick={open} />
              )}
            />
          )}
          {type === 'matching' && (
            <TextControl
              label={sprintf(__('Match %d', 'ohmylms'), index + 1)}
              value={option.matching_data?.label || ''}
              onChange={(label) =>
                patchOption(index, { matching_data: { ...option.matching_data, label } })
              }
            />
          )}
          {type === 'reorder' && (
            <>
              <Button disabled={index === 0} onClick={() => reorder(index, -1)}>
                {__('Move up', 'ohmylms')}
              </Button>
              <Button disabled={index === options.length - 1} onClick={() => reorder(index, 1)}>
                {__('Move down', 'ohmylms')}
              </Button>
            </>
          )}
          {type !== 'true-false' && (
            <Button
              icon="minus"
              label={__('Remove answer', 'ohmylms')}
              disabled={options.length <= (type === 'fill-in-the-blank' ? 1 : 2)}
              isDestructive
              variant="tertiary"
              onClick={() =>
                onChange({ questions: options.filter((_, position) => index !== position) })
              }
            ></Button>
          )}
          {type !== 'true-false' && (
            <Button
              icon="menu"
              label={__('Reorder answer', 'ohmylms')}
              draggable
              onDragStart={(event) => {
                dragged.current = index;
                event.dataTransfer.setData('text/plain', String(index));
              }}
              onDragEnd={() => {
                dragged.current = null;
              }}
              onKeyDown={(event) => {
                if (!event.altKey || !['ArrowUp', 'ArrowDown'].includes(event.key)) return;
                event.preventDefault();
                const target = index + (event.key === 'ArrowUp' ? -1 : 1);
                if (target >= 0 && target < options.length)
                  onChange({ questions: moveOption(options, index, target) });
              }}
            />
          )}
          {option.image_url && (
            <div className="ohmylms-shared-answer-image">
              <img src={option.image_url} alt={__('Answer image', 'ohmylms')} />
              <Button
                isDestructive
                variant="tertiary"
                onClick={() => patchOption(index, { thumbnail_id: 0, image_url: '' })}
              >
                {__('Remove image', 'ohmylms')}
              </Button>
            </div>
          )}
        </fieldset>
      ))}
      {type !== 'true-false' && (
        <Button
          variant="secondary"
          onClick={() =>
            onChange({
              questions: [
                ...options,
                {
                  answer: '',
                  is_correct: false,
                  order_number: options.length + 1,
                  matching_data: { label: '' },
                },
              ],
            })
          }
        >
          {__('Add answer', 'ohmylms')}
        </Button>
      )}
    </div>
  );
}
